package com.example.metadataui;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.web.servlet.MockMvc; import static org.hamcrest.Matchers.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class CustomerDetailControllerTest { @Autowired MockMvc mvc;
 @Test void discoversProvidersAcrossIndependentJars() throws Exception {mvc.perform(get("/api/ui/customer-detail/cards").param("customerId","1001")).andExpect(status().isOk()).andExpect(jsonPath("$.cards[*].code",contains("basic_info","friend_tags","behavior_trace")));}
 @Test void filtersByPermissionAndFeature() throws Exception {mvc.perform(get("/api/ui/customer-detail/cards").param("customerId","1001").header("X-Permissions","customer:read").header("X-Features","customerTags")).andExpect(status().isOk()).andExpect(jsonPath("$.cards",hasSize(1))).andExpect(jsonPath("$.cards[0].actions",hasSize(0)));}
}
